(() => {
  'use strict';
  const data=JSON.parse(document.getElementById('content-data').textContent);
  const entries=new Map(data.entries.map(e=>[e.id,e]));
  const subjects=new Map(data.subjects.map(s=>[s.slug,s]));
  const app=document.getElementById('app');
  const overlays=document.getElementById('overlays');
  const STORAGE='folio-math-progress-v1';
  const types={def:['定义','Definition'],thm:['定理','Theorem'],eg:['例子','Example'],roadmap:['路线','Roadmap'],exercise:['习题','Exercise'],mistake:['勘误','Correction']};
  const icons={
    book:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z"/><path d="M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3z"/>',
    grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v7a5 5 0 0 0 5 5h5M8 5h6a4 4 0 0 1 0 8h-4"/>',
    pen:'<path d="m15 4 5 5M4 20l4-1L20 7a2 2 0 0 0-4-4L4 15zM4 20h16"/>',
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
    code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 18"/>',
    arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
    back:'<path d="M20 12H4m6-6-6 6 6 6"/>',
    down:'<path d="m6 9 6 6 6-6"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
    close:'<path d="m6 6 12 12M18 6 6 18"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    bulb:'<path d="M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2"/>',
    link:'<path d="m9 15 6-6m-5-3 2-2a5 5 0 0 1 7 7l-2 2M7 11l-2 2a5 5 0 0 0 7 7l2-2"/>',
    download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
    upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',
    github:'<path d="M9 19c-5 1-5-3-7-3m14 6v-4a3 3 0 0 0-1-2c4-.4 6-2 6-6a5 5 0 0 0-1-3 5 5 0 0 0 0-4s-1 0-4 2a13 13 0 0 0-6 0C7 3 6 3 6 3a5 5 0 0 0 0 4 5 5 0 0 0-1 3c0 4 2 5.6 6 6a3 3 0 0 0-1 2v4"/>',
    leaf:'<path d="M20 4c-7-1-15 1-15 8a6 6 0 0 0 6 6c7 0 9-7 9-14ZM4 21 15 10"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 2M5 16a8 8 0 0 0 13 2"/>',
    file:'<path d="M14 2H5v20h14V7zM14 2v6h5M8 12h8m-8 4h6"/>',
    layers:'<path d="m12 3 10 5-10 5L2 8zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',
    external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>'
  };
  const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]??icons.book}</svg>`;
  const h=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
  const items=(subject,category)=>data.entries.filter(e=>e.subject===subject&&(!category||e.category===category)).sort((a,b)=>(a.order??99)-(b.order??99));
  const url=(subject,view='overview',id='')=>`#/${subject}/${view}${id?`/${id}`:''}`;
  const entryUrl=e=>url(e.subject,e.category,e.id);
  const mapPurpose=e=>e.purpose??'learn';
  const mapLabels={learn:'学习路线',review:'专题复习',practice:'刷题地图'};
  const maps=(subject,purpose)=>items(subject,'roadmap').filter(e=>!purpose||mapPurpose(e)===purpose);
  const entryView=e=>e.category==='roadmap'?(mapPurpose(e)==='practice'?'practice':'roadmaps'):({material:'materials',exercise:'exercises',mistake:'mistakes'})[e.category];
  const selectedView=view=>view==='roadmap'?(entries.has(current.id)?entryView(entries.get(current.id)):'roadmaps'):({material:'materials',exercise:'exercises',mistake:'mistakes'})[view]??view;
  const badge=e=>{const key=e.type??e.category;return `<span class="badge ${key}">${key==='roadmap'?mapPurpose(e).toUpperCase():key.toUpperCase()} <span>· ${key==='roadmap'?mapLabels[mapPurpose(e)]:types[key]?.[0]??''}</span></span>`;};
  const labels={overview:'学科概览',materials:'知识材料',roadmaps:'学习路线',practice:'刷题地图',exercises:'习题库',mistakes:'错题集',review:'学习记录',source:'内容与源码'};
  let progress={version:1,read:[],exercises:{},mistakes:{}};
  let storageAvailable=true;
  try {const saved=JSON.parse(localStorage.getItem(STORAGE)); if(saved?.version===1&&Array.isArray(saved.read)&&saved.exercises&&typeof saved.exercises==='object')progress=saved;}catch{storageAvailable=false;}
  if (!progress.mistakes || typeof progress.mistakes!=='object' || Array.isArray(progress.mistakes)) progress.mistakes={};
  const read=id=>progress.read.includes(id);
  const exerciseState=id=>progress.exercises[id]?.status??entries.get(id)?.initial_status??'new';
  const completed=id=>['completed','independent','assisted'].includes(exerciseState(id));
  const exerciseLabels={new:'未开始',attempted:'尝试中',completed:'已完成（导入记录）',independent:'独立完成',assisted:'提示后完成',review:'待重做'};
  const mistakeLabels={pending:'待复习',corrected:'已订正',mastered:'已掌握'};
  const mistakeState=id=>progress.mistakes[id]?.status??'pending';
  const filters={};
  const exerciseSessions={};
  const sourceVisible=new Set();
  const mapModes={};
  let modalName=null,previousFocus=null,toastTimer;
  let current={subject:data.subjects[0].slug,view:'overview',id:''};
  function save(){try{localStorage.setItem(STORAGE,JSON.stringify(progress));storageAvailable=true;}catch{storageAvailable=false;toast('浏览器未允许保存，可导出学习记录保留进度');}}
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);}
  function parseRoute(){const parts=location.hash.replace(/^#\/?/,'').split('/').map(x=>{try{return decodeURIComponent(x)}catch{return x}});return{subject:parts[0]||data.subjects[0].slug,view:parts[1]||'overview',id:parts[2]||''};}
  const roadmapMaterials=e=>[...new Set(e.blocks.filter(b=>b.kind==='material').map(b=>b.id))];
  function mapProgress(e){
    let ids,done,label;
    const questions=[...new Set(e.blocks.filter(b=>b.kind==='exercise').map(b=>b.id))];
    const corrections=[...new Set(e.blocks.filter(b=>b.kind==='mistake').map(b=>b.id))];
    if(mapPurpose(e)==='practice'){ids=questions;done=ids.filter(completed).length;label=`已完成 ${done} / ${ids.length} 道题`;}
    else if(mapPurpose(e)==='review'&&corrections.length){ids=corrections;done=ids.filter(id=>['corrected','mastered'].includes(mistakeState(id))).length;label=`已复习 ${done} / ${ids.length} 条要点`;}
    else {ids=roadmapMaterials(e);done=ids.filter(read).length;label=`已读 ${done} / ${ids.length} 份材料`;}
    return ids.length?{done,total:ids.length,label,percent:Math.round(done/ids.length*100)}:null;
  }
  function progressBar(value){return value?`<div class="progress-wrap"><div class="progress-label"><span>${h(value.label)}</span><span>${value.percent}%</span></div><div class="progress-track"><span style="width:${value.percent}%"></span></div></div>`:'';}
  function subjectHeader(s){return `<header class="subject-header"><div><div class="eyebrow">SUBJECT ${String(s.order).padStart(2,'0')} / YOUR MATHEMATICAL ATLAS</div><div class="subject-heading"><h1>${h(s.title)}</h1><span class="english">${h(s.english)}</span></div><p class="subject-description">${h(s.description)}</p></div><a class="btn secondary small" href="${url(s.slug,'source')}">${icon('code','sm')} 内容与源码</a></header>`;}
  function tabs(s,view){
    const selected=selectedView(view);
    const count=key=>key==='roadmaps'?maps(s.slug).filter(e=>mapPurpose(e)!=='practice').length:key==='practice'?maps(s.slug,'practice').length:key==='mistakes'?items(s.slug,'mistake').filter(e=>e.kind==='observed').length:items(s.slug,key.slice(0,-1)).length;
    return `<nav class="tabs" aria-label="学科内容">${[['overview','grid'],['materials','book'],['roadmaps','route'],['practice','pen'],['exercises','layers'],['mistakes','refresh']].map(([key,name])=>`<a class="tab ${selected===key?'active':''}" href="${url(s.slug,key)}" ${selected===key?'aria-current="page"':''}>${icon(name,'sm')}${labels[key]}${key==='overview'?'':`<span class="tab-count">${count(key)}</span>`}</a>`).join('')}</nav>`;
  }
  function shell(s,body){const totalRead=progress.read.filter(id=>entries.has(id)).length;return `<div class="sidebar-scrim" data-action="close-menu"></div><aside class="sidebar" aria-label="学科导航"><a class="brand" href="${url(data.subjects[0].slug)}" aria-label="Folio 首页"><span class="brand-mark">f<span style="color:#c1cb99">.</span></span><div><div class="brand-name">folio<span>.</span></div><div class="brand-sub">数学手记</div></div></a><div class="sidebar-label">我的学科 <span style="float:right;font:9px var(--mono)">${String(data.subjects.length).padStart(2,'0')}</span></div><nav>${data.subjects.map(subject=>`<a class="side-subject ${s.slug===subject.slug?'active':''}" href="${url(subject.slug)}" ${s.slug===subject.slug?'aria-current="true"':''}><span class="subject-symbol">${h(subject.symbol)}</span><span>${h(subject.title)}</span><span class="count">${String(items(subject.slug,'material').length).padStart(2,'0')}</span></a>`).join('')}</nav><div class="sidebar-label">学习空间</div><button class="side-utility" data-action="search">${icon('search','sm')} 搜索知识</button><a class="side-utility" href="${url(s.slug,'review')}">${icon('refresh','sm')} 我的学习记录 <span class="spacer"></span><span style="font:9px var(--mono)">${totalRead}</span></a><a class="side-utility" href="${url(s.slug,'mistakes')}">${icon('pen','sm')} 错题与复盘</a><button class="side-utility" data-action="github">${icon('github','sm')} GitHub 工作流</button><div class="sidebar-bottom"><div class="small-note">让定义成为语言，<br>让理解慢慢生长。</div><div class="local-note"><i class="dot"></i>${storageAvailable?'学习记录保存在此设备':'当前浏览器无法持久保存'}</div><div class="profile"><span class="avatar">∴</span><div><div class="profile-name">我的数学手记</div><small>PERSONAL LEARNING SPACE</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="row"><button class="icon-button mobile-menu" data-action="menu" aria-label="打开学科导航">${icon('menu')}</button><div class="breadcrumbs"><span class="crumb-home">我的学习空间</span><span class="crumb-home">/</span><strong>${h(s.title)}</strong><span>/</span><span>${h(labels[selectedView(current.view)]??'知识详情')}</span></div></div><div class="top-actions"><button class="search-trigger" data-action="search">${icon('search','sm')} 搜索定义、定理、例子… <kbd>⌘ K</kbd></button><span class="version-pill">DEMO · 0.1</span></div></header><main id="main" class="page" tabindex="-1">${subjectHeader(s)}${tabs(s,current.view)}${body}<footer class="page-footer"><span>FOLIO / 每一份理解，都从一个定义开始。</span><span>Mathematics, connected.</span></footer></main></div>`;}
  function roadmapCard(e,compact=false){
    const purpose=mapPurpose(e),value=mapProgress(e),ids=roadmapMaterials(e);
    const questions=e.blocks.filter(b=>b.kind==='exercise').length;
    const headings=e.blocks.filter(b=>b.kind==='prose').flatMap(b=>[...b.text.matchAll(/^## (.+)$/gm)].map(m=>m[1].replace(/^\d+\s*·\s*/,'')));
    const action=purpose==='practice'?(value?.done?'继续刷题':'进入题组'):purpose==='review'?'开始复习':ids.length?'查看知识脉络':'查看导读';
    return `<article class="roadmap-panel ${purpose==='practice'?'practice-map-card':''}"><div class="row between">${badge(e)}<span class="tag">${h(e.study_date??e.level??'专题')}</span></div><h3><a href="${entryUrl(e)}">${h(e.title)}</a></h3><p>${h(e.summary)}</p><div class="course-info">${purpose==='practice'?`<span>${icon('pen','sm')}${questions} 道习题</span>`:ids.length?`<span>${icon('layers','sm')}${ids.length} 个知识节点</span>`:''}<span>${icon('clock','sm')}约 ${e.minutes??5} 分钟</span></div>${purpose!=='practice'&&headings.length?`<div class="map-outline">${headings.slice(0,4).map(title=>`<span>${h(title)}</span>`).join('')}</div>`:''}<div class="course-footer">${progressBar(value)}<a class="btn ${compact?'secondary':'primary'} small" href="${entryUrl(e)}">${action} ${icon('arrow','sm')}</a></div></article>`;
  }
  function materialCard(e){return `<a class="material-card" href="${entryUrl(e)}"><div class="row between">${badge(e)}<span class="read-dot ${read(e.id)?'done':''}" aria-label="${read(e.id)?'已读':'未读'}">${read(e.id)?'✓':''}</span></div><h3 class="card-title">${h(e.title)}</h3><div class="card-english">${h(e.english)}</div><p class="card-summary">${h(e.summary)}</p><div class="card-footer"><span class="row" style="gap:4px">${icon('clock','sm')}${e.minutes??5} 分钟</span><span class="row tags" style="gap:5px">${(e.tags??[]).slice(0,2).map(t=>`<span>${h(t)}</span>`).join('<span>·</span>')}</span>${icon('arrow','sm')}</div></a>`;}
  function subjectHighlights(s){
    return (s.highlights??(s.featured?[s.featured]:[])).map(id=>entries.get(id)).filter(e=>e?.category==='material'&&e.subject===s.slug);
  }
  function highlightCard(e,index){
    const primary=index===0,statement=e.blocks.find(b=>['statement','example'].includes(b.kind));
    const showStatement=primary&&statement&&statement.text.trim().length<=560;
    const statementLabel=e.type==='thm'?'条件与结论':e.type==='def'?'核心定义':'核心内容';
    const proof=e.blocks.some(b=>b.kind==='proof');
    return `<article class="highlight-card ${primary?'highlight-primary':'highlight-secondary'}" data-highlight-id="${h(e.id)}" aria-labelledby="highlight-${h(e.id)}-title">
      <div class="highlight-meta"><div class="row wrap">${badge(e)}<span class="highlight-position">${String(index+1).padStart(2,'0')} / 重点</span></div><button class="read-button ${read(e.id)?'done':''}" data-action="read" data-id="${h(e.id)}" aria-label="${read(e.id)?'取消已读':'标记已读'}：${h(e.title)}" aria-pressed="${read(e.id)}">${read(e.id)?'✓':icon('check','sm')}</button></div>
      <h3 id="highlight-${h(e.id)}-title"><a href="${entryUrl(e)}">${h(e.title)}</a></h3>
      <p class="highlight-summary">${h(e.summary)}</p>
      ${showStatement?`<div class="highlight-statement"><div class="highlight-statement-label">${statementLabel}</div><div class="prose">${statement.html}</div></div>`:`${e.formulaHtml?`<div class="highlight-formula">${e.formulaHtml}</div>`:''}${statement?`<details class="highlight-details"><summary>展开${statementLabel} ${icon('down','sm')}</summary><div class="prose">${statement.html}</div></details>`:''}`}
      <div class="highlight-footer"><span>${read(e.id)?'已读':'待回看'} · ${e.minutes??5} 分钟</span><a class="text-link" href="${entryUrl(e)}">${proof?'阅读陈述与证明':'阅读完整材料'} ${icon('arrow','sm')}</a></div>
    </article>`;
  }
  function highlightSection(list){
    if(!list.length)return '';
    return `<section class="subject-highlights" aria-labelledby="subject-highlights-title"><div class="section-head"><div><h2 id="subject-highlights-title">${icon('bulb','sm')} 重要结论 <span class="english-label">Key results</span></h2><p class="highlight-intro">把条件和结论一起记住。</p></div><span class="highlight-count">${list.length} 条重点</span></div><div class="highlight-grid ${list.length===1?'highlight-grid-single':''}">${highlightCard(list[0],0)}${list.length>1?`<div class="highlight-secondary-list">${list.slice(1).map((e,i)=>highlightCard(e,i+1)).join('')}</div>`:''}</div></section>`;
  }
  function overview(s){
    const mats=items(s.slug,'material'),routes=maps(s.slug).filter(e=>mapPurpose(e)!=='practice'),exercises=items(s.slug,'exercise'),primary=entries.get(s.primaryRoadmap);
    const highlights=subjectHighlights(s),highlightIds=new Set(highlights.map(e=>e.id));
    const remaining=mats.filter(e=>!highlightIds.has(e.id));
    const selected=[...new Map([remaining.find(e=>e.type==='def'),remaining.find(e=>e.type==='eg'),...remaining].filter(Boolean).map(e=>[e.id,e])).values()].slice(0,3);
    return `${highlightSection(highlights)}
      <section class="overview-learning" aria-labelledby="overview-learning-title"><div class="section-head"><h2 id="overview-learning-title">${icon('route','sm')} 推荐学习路线 <span class="english-label">Learning path</span></h2><a class="text-link" href="${url(s.slug,'roadmaps')}">全部路线 ${icon('arrow','sm')}</a></div><div class="overview-grid">${roadmapCard(primary)}<aside class="subject-note"><div class="eyebrow">A PATH TO UNDERSTANDING</div><p>${h(s.quote)}</p><a class="btn white small" href="${url(s.slug,'materials')}">浏览知识材料 ${icon('arrow','sm')}</a></aside></div></section>
      ${studyDigest(s)}
      <section class="stats" aria-label="学科内容统计">${[['book',mats.length,'份','知识材料','Definitions · Theorems · Examples'],['route',routes.length,'条','学习路线','A connected way to learn'],['pen',exercises.length,'道','训练习题','Practice makes it yours']].map(([name,count,unit,label,en])=>`<div class="stat"><span class="stat-icon">${icon(name)}</span><div><div class="stat-number">${String(count).padStart(2,'0')}<span>${unit} ${label}</span></div><div class="stat-label">${en}</div></div></div>`).join('')}</section>
      ${selected.length?`<section><div class="section-head"><h2>${icon('book','sm')} 从这些材料开始 <span class="english-label">Selected materials</span></h2><a class="text-link" href="${url(s.slug,'materials')}">全部 ${mats.length} 份 ${icon('arrow','sm')}</a></div><div class="material-grid">${selected.map(materialCard).join('')}</div></section>`:''}`;
  }
  function materialList(s){const filter=filters[s.slug]??={type:'all',query:''};return `<div class="filters" role="group" aria-label="筛选材料类型">${[['all','全部材料'],['def','def · 定义'],['thm','thm · 定理'],['eg','eg · 例子']].map(([type,label])=>`<button class="filter-chip ${filter.type===type?'active':''}" data-action="filter" data-type="${type}" aria-pressed="${filter.type===type}">${label}</button>`).join('')}<label class="inline-search">${icon('search','sm')}<input id="material-query" type="search" placeholder="搜索当前学科…" aria-label="搜索当前学科材料" value="${h(filter.query)}"></label></div><div id="material-results"></div>`;}
  function updateMaterialResults(){const el=document.getElementById('material-results');if(!el)return;const filter=filters[current.subject]??{type:'all',query:''};const query=filter.query.trim().toLowerCase();const found=items(current.subject,'material').filter(e=>(filter.type==='all'||e.type===filter.type)&&query.split(/\s+/).every(q=>e.searchText.includes(q)));el.innerHTML=`<div class="result-meta">${query?'找到':'共'} ${found.length} 份材料${filter.type!=='all'?` · ${types[filter.type][0]}`:''}</div>${found.length?`<div class="material-grid">${found.map(materialCard).join('')}</div>`:emptyState('没有找到相关材料','试试英文别名、中文名称或标签。')}`;}
  function emptyState(title,text){return `<div class="empty-state">${icon('leaf')}<h3>${h(title)}</h3><p>${h(text)}</p></div>`;}
  const blockLabels={statement:['正式陈述','Statement'],intuition:['直观理解','Intuition'],remark:['留意这一点','Remark'],example:['具体例子','Example'],goal:['这条路线的目标','Learning goal'],problem:['试着独立完成','Problem'],solution:['参考解答','Solution'],original:['原想法 / 风险','Original thought'],correction:['正确认识','Correction'],counterexample:['反例 / 检验','Counterexample'],reviewtask:['闭卷复习任务','Retrieval practice']};
  function blockHtml(b){if(b.kind==='prose')return `<div class="prose">${b.html}</div>`;if(b.kind==='proof')return `<details class="proof-block semantic-block"><summary>${icon('book','sm')} 展开证明 <span class="serif muted">Proof</span>${icon('down','sm chevron')}</summary><div class="proof-content"><div class="prose">${b.html}</div><div class="qed">□</div></div></details>`;const labels=blockLabels[b.kind]??[b.kind,''];return `<section class="semantic-block ${['statement','remark','goal','original','correction','reviewtask'].includes(b.kind)?`${b.kind}-block`:''}"><div class="block-label">${labels[0]} <span>${labels[1]}</span></div><div class="prose">${b.html}</div></section>`;}
  function sourcePane(e){return `<aside class="source-pane ${sourceVisible.has(e.id)?'show':''}" aria-label="原始 Markdown"><div class="source-top">${icon('file','sm')}<span class="filename" title="${h(e.source)}">${h(e.source.split('/').slice(-2).join('/'))}</span><a class="btn ghost small" href="source/${h(e.source)}" download>${icon('download','sm')} MD</a></div><pre class="source-code"><code>${h(e.raw)}</code></pre></aside>`;}
  function detailHeader(e){
    const view=entryView(e),backId=e.category==='roadmap'&&mapPurpose(e)==='review'?'review':'';
    const backLabel=e.category==='roadmap'?mapLabels[mapPurpose(e)]:({material:'材料库',exercise:'习题库',mistake:'错题集'})[e.category];
    return `<a class="detail-back" href="${url(e.subject,view,backId)}">${icon('back','sm')} 返回${backLabel}</a><header class="detail-header">${badge(e)}<h1>${h(e.title)}</h1><div class="english">${h(e.english)}</div><div class="detail-tools">${e.category==='material'?`<button class="btn ${read(e.id)?'secondary':'primary'} small" data-action="read" data-id="${e.id}" aria-pressed="${read(e.id)}">${icon('check','sm')}${read(e.id)?'已读 · 取消标记':'标记为已读'}</button>`:''}<button class="btn secondary small" data-action="source" data-id="${e.id}" aria-pressed="${sourceVisible.has(e.id)}">${icon('code','sm')}${sourceVisible.has(e.id)?'收起 Markdown':'对照 Markdown'}</button><span class="row muted" style="font-size:10px;gap:5px">${icon('clock','sm')}约 ${e.minutes??5} 分钟</span>${(e.tags??[]).map(t=>`<span class="tag">${h(t)}</span>`).join('')}</div></header>`;
  }
  function materialDetail(e){return `${detailHeader(e)}<div class="detail-grid ${sourceVisible.has(e.id)?'comparing':''}"><div class="article-layout"><article class="article-card">${e.blocks.map(blockHtml).join('')}</article></div>${sourcePane(e)}${relatedAside(e)}</div>${sourceVisible.has(e.id)?'<p class="source-notice">同一份 Markdown 提供数学内容，网页组件决定视觉布局与交互。</p>':''}`;}
  function embedMaterial(e){const statement=e.blocks.find(b=>['statement','example'].includes(b.kind)),proof=e.blocks.find(b=>b.kind==='proof');return `<article class="embedded-material"><div class="embed-head">${badge(e)}<h3><a href="${entryUrl(e)}">${h(e.title)}</a></h3><button class="read-button ${read(e.id)?'done':''}" data-action="read" data-id="${e.id}" aria-label="${read(e.id)?'取消已读':'标记已读'}：${h(e.title)}" aria-pressed="${read(e.id)}">${read(e.id)?'✓':icon('check','sm')}</button></div><div class="embed-body"><div class="prose">${statement?.html??h(e.summary)}</div>${proof?blockHtml(proof):''}</div><div class="embed-footer"><span>${h(e.english)}</span><a class="text-link" href="${entryUrl(e)}">完整材料与源码 ${icon('arrow','sm')}</a></div></article>`;}
  function embedExercise(e){return `<a class="embedded-exercise" href="${entryUrl(e)}"><span class="exercise-no">✎</span><div><strong>${h(e.title)}</strong><small>${h(e.difficulty)} · ${e.minutes} 分钟 · ${h(exerciseLabels[exerciseState(e.id)])}</small></div>${icon('arrow','sm')}</a>`;}
  function outlineMaterial(e,index){
    const statement=e.blocks.find(b=>['statement','example'].includes(b.kind));
    return `<article class="map-node"><span class="map-node-number">${String(index+1).padStart(2,'0')}</span><div class="map-node-content"><div class="row wrap">${badge(e)}<span class="muted map-node-time">${e.minutes??5} 分钟</span></div><h3><a href="${entryUrl(e)}">${h(e.title)}</a></h3><p>${h(e.summary)}</p>${statement?`<details class="map-node-detail"><summary>展开核心陈述 ${icon('down','sm')}</summary><div class="prose">${statement.html}</div><a class="text-link" href="${entryUrl(e)}">阅读完整解释与证明 ${icon('arrow','sm')}</a></details>`:''}</div><button class="read-button ${read(e.id)?'done':''}" data-action="read" data-id="${e.id}" aria-label="${read(e.id)?'取消已读':'标记已读'}：${h(e.title)}" aria-pressed="${read(e.id)}">${read(e.id)?'✓':icon('check','sm')}</button></article>`;
  }
  function roadmapDetail(e){
    const purpose=mapPurpose(e),ids=roadmapMaterials(e),mode=mapModes[e.id]??'outline';
    let index=0;
    return `${detailHeader(e)}<div class="route-heading"><p class="route-header-description">${h(e.summary)}</p><div class="route-progress">${progressBar(mapProgress(e))}</div>${purpose!=='practice'&&ids.length?`<div class="map-view-bar"><div class="filters" role="group" aria-label="路线阅读方式">${[['outline','知识速览'],['reading','展开阅读']].map(([key,label])=>`<button class="filter-chip ${mode===key?'active':''}" data-action="map-mode" data-id="${e.id}" data-mode="${key}" aria-pressed="${mode===key}">${label}</button>`).join('')}</div><span>先看知识脉络，需要时再读证明。</span></div>`:''}</div><div class="detail-grid ${sourceVisible.has(e.id)?'comparing':''}"><div class="roadmap-content ${mode==='outline'?'map-overview':''}">${e.blocks.map(b=>b.kind==='material'?(mode==='reading'?embedMaterial(entries.get(b.id)):outlineMaterial(entries.get(b.id),index++)):b.kind==='exercise'?embedExercise(entries.get(b.id)):b.kind==='mistake'?mistakeCard(entries.get(b.id)):blockHtml(b)).join('')}</div>${sourcePane(e)}${relatedAside(e)}</div>`;
  }
  function exerciseDetail(e){const session=exerciseSessions[e.id]??={hints:progress.exercises[e.id]?.hintsUsed??0,solution:false};const problem=e.blocks.find(b=>b.kind==='problem'),hints=e.blocks.filter(b=>b.kind==='hint'),solution=e.blocks.find(b=>b.kind==='solution');return `${detailHeader(e)}${studyMetadata(e)}<div class="detail-grid ${sourceVisible.has(e.id)?'comparing':''}"><article class="article-card"><section class="exercise-problem">${blockHtml(problem)}</section>${hints.length?`<section class="hint-section"><div class="row between"><span class="hint-title">${icon('bulb','sm')} 分层提示 <span style="font:9px var(--mono);margin-left:5px">${session.hints} / ${hints.length}</span></span><button class="btn secondary small" data-action="hint" data-id="${e.id}" ${session.hints>=hints.length?'disabled':''}>${session.hints>=hints.length?'提示已全部展开':'给我一点提示'} ${icon('down','sm')}</button></div>${hints.slice(0,session.hints).map((b,i)=>`<div class="prose"><span style="font:9px var(--mono)">HINT ${i+1}</span>${b.html}</div>`).join('')}</section>`:''}${solution?(session.solution?`<section class="semantic-block"><div class="block-label">参考解答 <span>Solution</span><button class="btn ghost small" data-action="solution" data-id="${e.id}" style="margin-left:auto">收起</button></div><div class="prose">${solution.html}</div></section>`:`<div class="solution-gate"><p>先给自己一点独立思考的时间，再对照解答。</p><button class="btn secondary small" data-action="solution" data-id="${e.id}">${icon('book','sm')} 展开参考解答</button></div>`):''}${exerciseSupplements(e)}<div class="self-assessment"><p>这一次，你完成得怎么样？</p><div class="row wrap">${[['independent','独立完成'],['assisted','借助提示完成'],['review','还需重做']].map(([key,label])=>`<button class="btn secondary small ${exerciseState(e.id)===key?'selected':''}" data-action="assess" data-status="${key}" data-id="${e.id}" aria-pressed="${exerciseState(e.id)===key}">${exerciseState(e.id)===key?icon('check','sm'):''}${label}</button>`).join('')}</div><p class="completion-note">当前状态：${exerciseLabels[exerciseState(e.id)]} · 证明题由你对照关键步骤自评</p></div></article>${sourcePane(e)}${relatedAside(e)}</div>`;}
  function sourcePage(s){const sample=entries.get(s.featured);return `<p class="overview-source-explanation">你编辑数学内容，网页组织阅读体验。材料、路线与习题都属于当前学科；相同内容可以在不同页面里呈现。</p><div class="architecture"><div><strong>01 · 写内容</strong><small>Markdown + 语义标记</small></div><span class="arrow muted">→</span><div><strong>02 · 识别结构</strong><small>陈述、证明、引用、提示</small></div><span class="arrow muted">→</span><div><strong>03 · 生成体验</strong><small>材料卡片、路线、习题训练</small></div></div><div class="section-head"><h2>同一材料的两种视角</h2><a class="text-link" href="${entryUrl(sample)}">打开完整材料 ${icon('arrow','sm')}</a></div><div class="detail-grid comparing"><article class="article-card">${sample.blocks.map(blockHtml).join('')}</article><aside class="source-pane show"><div class="source-top">${icon('file','sm')}<span class="filename">${h(sample.source)}</span><a class="btn ghost small" href="source/${h(sample.source)}" download>${icon('download','sm')} MD</a></div><pre class="source-code"><code>${h(sample.raw)}</code></pre></aside></div><p class="source-notice">修改右侧文件后重新构建，材料详情、路线引用和检索内容会一起更新。</p>`;}
  function notebookAction(target) {
    const action=target.dataset.action,id=target.dataset.id;
    if (action==='mistake-filter') {
      filters[`mistakes-${current.subject}`].kind=target.dataset.kind;
      render(true);
      return true;
    }
    if (action!=='mistake-assess' && action!=='mistake-note-save') return false;
    if (entries.get(id)?.category!=='mistake') return true;
    progress.mistakes??={};
    const existing=progress.mistakes[id]??{};
    const note=(document.getElementById('mistake-note')?.value??existing.note??'').slice(0,4000);
    progress.mistakes[id]={...existing,note,status:existing.status??'pending'};
    if (action==='mistake-assess' && Object.hasOwn(mistakeLabels,target.dataset.status)) {
      progress.mistakes[id].status=target.dataset.status;
      progress.mistakes[id].lastReviewedAt=new Date().toISOString();
    }
    save();
    render(true);
    toast(action==='mistake-assess'?'已保存勘误复习状态':'复盘笔记已保存');
    return true;
  }
  function revealActiveTab() {
    const tab=document.querySelector('.tabs .active'),nav=tab?.parentElement;
    if (!nav || nav.scrollWidth<=nav.clientWidth) return;
    const right=tab.getBoundingClientRect().right-nav.getBoundingClientRect().right;
    if (right>0) nav.scrollLeft+=right+10;
  }
  function studyMetadata(e) {
    if (!e.study_date && !e.source_note) return '';
    return `<div class="study-metadata"><div class="row wrap"><span class="badge">${h(e.id)}</span>${e.study_date?`<span>${h(e.study_date)}</span>`:''}${e.track?`<span>· ${h(e.track)}</span>`:''}${e.chapter?`<span>· ${h(e.chapter)}</span>`:''}${e.imported_status?`<span class="tag">导入时：${h(e.imported_status)}</span>`:''}${e.kind?`<span class="tag">${e.kind==='observed'?'原包标注：已发生的误区':'原包标注：建议复习，未记作已犯错误'}</span>`:''}</div>${e.source_note?`<details class="source-provenance"><summary>题目来源${e.source_verified===false?' · 题号待核对':''}</summary><p>${h(e.source_note)}</p></details>`:''}</div>`;
  }

  function studyDigest(s){
    const sets=maps(s.slug,'practice');
    if(!sets.length)return '';
    return `<div class="practice-shortcut"><span>${icon('pen','sm')} 用习题检验理解 · ${sets.length} 张刷题地图</span><a class="text-link" href="${url(s.slug,'practice')}">按主题或日期选择题组 ${icon('arrow','sm')}</a></div>`;
  }
  function mistakeCard(e) {
    const status=mistakeState(e.id);
    return `<article class="mistake-card"><div class="row between"><span class="badge ${e.kind==='observed'?'mistake':'review-point'}">${e.kind==='observed'?'已记录误区':'复习提醒'}</span><span class="mistake-status ${status}">${h(mistakeLabels[status])}</span></div><h3><a href="${entryUrl(e)}">${h(e.title)}</a></h3><p>${h(e.summary)}</p><div class="mistake-question-links">${(e.related_questions??[]).map(id=>`<a href="${entryUrl(entries.get(id))}">${icon('link','sm')} ${h(id)} · ${h(entries.get(id).title)}</a>`).join('')}</div><div class="mistake-card-footer"><span>${h(e.id)}${e.study_date?` · ${h(e.study_date)}`:''}</span><a class="text-link" href="${entryUrl(e)}">订正与复盘 ${icon('arrow','sm')}</a></div></article>`;
  }
  function mistakesList(s) {
    const state=filters[`mistakes-${s.slug}`]??={kind:'observed',status:'all',query:''};
    const records=items(s.slug,'mistake');
    const observed=records.filter(e=>e.kind==='observed').length;
    const suggested=records.filter(e=>e.kind==='suggested').length;
    const redo=items(s.slug,'exercise').filter(e=>exerciseState(e.id)==='review').length;
    return `<section class="notebook-intro"><div><div class="eyebrow">CORRECT · RECALL · REBUILD</div><h2>把一次卡住，变成下一次理解。</h2><p>已发生的误区、建议复习的要点和待复做习题分别记录。订正状态与个人复盘笔记保存在此设备。</p></div><div class="notebook-counts"><span><strong>${observed}</strong>已记录误区</span><span><strong>${suggested}</strong>复习提醒</span><span><strong>${redo}</strong>待复做题</span></div></section><div class="filters notebook-filters" role="group" aria-label="错题集分类">${[['observed',`已记录误区 ${observed}`],['suggested',`复习提醒 ${suggested}`],['redo',`待复做题 ${redo}`]].map(([kind,label])=>`<button class="filter-chip ${state.kind===kind?'active':''}" data-action="mistake-filter" data-kind="${kind}" aria-pressed="${state.kind===kind}">${label}</button>`).join('')}<label class="inline-search">${icon('search','sm')}<input id="mistake-query" type="search" placeholder="搜索勘误、题号或要点…" aria-label="搜索错题集" value="${h(state.query)}"></label></div><div class="notebook-toolbar"><p id="notebook-context"></p><label class="notebook-status-filter">复习状态 <select id="mistake-status" aria-label="筛选勘误复习状态" ${state.kind==='redo'?'disabled':''}>${[['all','全部状态'],...Object.entries(mistakeLabels)].map(([key,label])=>`<option value="${key}" ${state.status===key?'selected':''}>${label}</option>`).join('')}</select></label></div><div id="mistake-results"></div>`;
  }
  function updateMistakeResults() {
    const target=document.getElementById('mistake-results');
    if (!target) return;
    const state=filters[`mistakes-${current.subject}`];
    const words=state.query.trim().toLowerCase().split(/\s+/);
    document.getElementById('notebook-context').textContent=state.kind==='suggested'?'这些是原包建议复习的薄弱环节，不代表已经犯过这些错误。':state.kind==='redo'?'在任一道习题中选择「还需重做」，它会进入这里；完成自评后会移出待复做列表。':'这些记录由原包标注为讨论中已出现的误区。先读订正，再用闭卷任务检查理解。';
    if (state.kind==='redo') {
      const list=items(current.subject,'exercise').filter(e=>exerciseState(e.id)==='review'&&words.every(q=>e.searchText.includes(q)));
      target.innerHTML=list.length?`<div class="exercise-list">${list.map(embedExercise).join('')}</div>`:emptyState('暂时没有待复做习题','需要重新练习时，在题目页选择「还需重做」。');
      return;
    }
    const list=items(current.subject,'mistake').filter(e=>e.kind===state.kind&&(state.status==='all'||mistakeState(e.id)===state.status)&&words.every(q=>e.searchText.includes(q)));
    target.innerHTML=list.length?`<div class="mistake-grid">${list.map(mistakeCard).join('')}</div>`:emptyState('这里还没有相关记录',state.kind==='observed'?'这个学科暂时没有已记录的误区；可切换到待复做题，或调整筛选。':'试试其他关键词或复习状态。');
  }
  function mistakeDetail(e) {
    const state=mistakeState(e.id),note=progress.mistakes[e.id]?.note??'';
    const original=e.blocks.find(b=>b.kind==='original');
    const rest=e.blocks.filter(b=>b!==original);
    const originalHtml=original?`<section class="semantic-block original-block"><div class="block-label">${e.kind==='observed'?'当时的想法':'需要留意的风险'} <span>${e.kind==='observed'?'Recorded misconception':'Suggested review point'}</span></div><div class="prose">${original.html}</div></section>`:'';
    return `${detailHeader(e)}${studyMetadata(e)}<div class="detail-grid ${sourceVisible.has(e.id)?'comparing':''}"><article class="article-card">${originalHtml}${rest.map(blockHtml).join('')}<section class="mistake-assessment"><h2>这条认识，你掌握了吗？</h2><div class="row wrap">${Object.entries(mistakeLabels).map(([key,label])=>`<button class="btn secondary small ${state===key?'selected':''}" data-action="mistake-assess" data-id="${e.id}" data-status="${key}" aria-pressed="${state===key}">${state===key?icon('check','sm'):''}${label}</button>`).join('')}</div><p class="completion-note">当前：${h(mistakeLabels[state])} · 订正和掌握由你自评，不会自动改写原题完成状态。</p><label class="mistake-note-label" for="mistake-note">我的复盘笔记</label><textarea id="mistake-note" maxlength="4000" rows="4" placeholder="写下这次卡住的原因、判断前提的方法，或下一次想怎样证明…">${h(note)}</textarea><div class="row between"><small class="muted">仅保存到当前浏览器，可随学习记录一起导出。</small><button class="btn primary small" data-action="mistake-note-save" data-id="${e.id}">保存复盘笔记</button></div></section></article>${sourcePane(e)}${relatedAside(e)}</div>`;
  }
  function exerciseSupplements(e) {
    const blocks=e.blocks.filter(b=>!['problem','hint','solution'].includes(b.kind));
    return blocks.length?`<section class="exercise-supplement">${blocks.map(blockHtml).join('')}</section>`:'';
  }
  function exercisesList(s) {
    const filter=filters[`ex-${s.slug}`]??'all',selectedDate=filters[`exdate-${s.slug}`]??'all';
    const all=items(s.slug,'exercise');
    const dates=[...new Set(all.map(e=>e.study_date).filter(Boolean))].sort().reverse();
    const list=all.filter(e=>(selectedDate==='all'||e.study_date===selectedDate)&&(filter==='all'||(filter==='todo'&&!completed(e.id))||(filter==='done'&&completed(e.id)))).sort((a,b)=>(b.study_date??'').localeCompare(a.study_date??'')||(a.order??99)-(b.order??99));
    return `<div class="filters">${[['all','全部习题'],['todo','未完成'],['done','已完成']].map(([key,label])=>`<button class="filter-chip ${filter===key?'active':''}" data-action="exercise-filter" data-type="${key}" aria-pressed="${filter===key}">${label}</button>`).join('')}${dates.length?`<label class="exercise-date-filter">题组 <select id="exercise-date" aria-label="按日期筛选题组"><option value="all">全部日期</option>${dates.map(date=>`<option value="${date}" ${selectedDate===date?'selected':''}>${date}</option>`).join('')}</select></label>`:''}<span class="spacer"></span><a class="text-link" href="${url(s.slug,'mistakes')}">错题集 ${icon('arrow','sm')}</a><span class="muted" style="font-size:10px">已完成 ${all.filter(e=>completed(e.id)).length} / ${all.length}</span></div><div class="exercise-list">${list.length?list.map((e,i)=>`<a class="exercise-row" href="${entryUrl(e)}"><span class="exercise-no">${String(i+1).padStart(2,'0')}</span><div><div class="row wrap">${badge(e)}<span class="tag">${h(e.difficulty)}</span><span class="muted" style="font-size:9px">${e.minutes} 分钟</span>${e.study_date?`<span class="tag">${h(e.study_date)}</span><span class="tag">${h(e.id)}</span>`:''}</div><h2 class="exercise-title">${h(e.title)}</h2><p class="exercise-summary">${h(e.summary)}</p></div><span class="exercise-status">${h(exerciseLabels[exerciseState(e.id)])}</span>${icon('arrow','sm')}</a>`).join(''):emptyState('这里暂时没有习题','切换筛选，或从学习路线继续。')}</div>`;
  }
  function relatedAside(e) {
    const required=(e.requires??e.targets??[]).map(id=>entries.get(id));
    const linked=[...new Set([...e.backlinks,...(e.related??[]),...(e.related_questions??[]),...(e.mistake_ids??[])])].map(id=>entries.get(id));
    const materials=linked.filter(x=>x.category==='material'&&!required.some(ref=>ref.id===x.id));
    const routes=linked.filter(x=>x.category==='roadmap'),questions=linked.filter(x=>x.category==='exercise'),mistakes=linked.filter(x=>x.category==='mistake');
    const group=(title,name,list)=>list.length?`<section class="aside-panel"><h2 class="aside-title">${icon(name,'sm')}${title}</h2><div class="aside-list">${list.map(ref=>`<a href="${entryUrl(ref)}">${icon(name,'sm')}<span>${h(ref.title)}${ref.category==='mistake'?`<small class="related-kind">${ref.kind==='observed'?'已记录误区':'复习提醒'}</small>`:''}</span></a>`).join('')}</div></section>`:'';
    return `<aside class="detail-aside">${required.length?`<section class="aside-panel"><h2 class="aside-title">${icon('layers','sm')}${e.category==='exercise'?'这道题考查什么':e.category==='mistake'?'对应知识卡':'预备知识'}</h2><div class="aside-list">${required.map(ref=>`<a href="${entryUrl(ref)}">${badge(ref)}<span>${h(ref.title)}</span></a>`).join('')}</div></section>`:''}${group('关联知识','link',materials)}${group('学习路线','route',routes.filter(r=>mapPurpose(r)==='learn'))}${group('专题复习','refresh',routes.filter(r=>mapPurpose(r)==='review'))}${group('刷题地图','pen',routes.filter(r=>mapPurpose(r)==='practice'))}${group(e.category==='mistake'?'关联原题':e.category==='exercise'?'关联习题':'试着用一用','pen',questions)}${group('勘误与复习要点','refresh',mistakes)}<section class="aside-panel"><h2 class="aside-title">${icon('file','sm')}内容归属</h2><p>${h(subjects.get(e.subject).title)} / ${h(({material:'materials',roadmap:'roadmaps',exercise:'exercises',mistake:'mistakes'})[e.category])}</p><p style="margin-top:7px">永久 ID<br><code style="font:9px var(--mono)">${h(e.id)}</code></p></section></aside>`;
  }

  function reviewPage(s){const readItems=data.entries.filter(e=>e.category==='material'&&read(e.id));const exercises=data.entries.filter(e=>e.category==='exercise'&&exerciseState(e.id)!=='new');return `<div class="section-head"><h2>每一步理解，都值得留下</h2><div class="row"><button class="btn secondary small" data-action="export">${icon('download','sm')}导出记录</button><button class="btn secondary small" data-action="import">${icon('upload','sm')}导入记录</button></div></div><p class="overview-source-explanation">这里汇集所有学科的学习记录。阅读和做题分别计数，记录保存在当前浏览器；导出文件可用于备份或迁移到另一台设备。</p><div class="review-grid"><section class="review-card"><div class="row between"><h3>已读材料</h3><span class="review-stat">${String(readItems.length).padStart(2,'0')}</span></div><div class="review-list">${readItems.length?readItems.map(e=>`<a href="${entryUrl(e)}">${badge(e)}${h(e.title)}${icon('arrow','sm')}</a>`).join(''):'<p>读完一份材料后，点击「标记为已读」。</p>'}</div></section><section class="review-card"><div class="row between"><h3>习题记录</h3><span class="review-stat">${String(exercises.filter(e=>completed(e.id)).length).padStart(2,'0')}</span></div><div class="review-list">${exercises.length?exercises.map(e=>`<a href="${entryUrl(e)}"><span class="badge exercise">${exerciseLabels[exerciseState(e.id)]}</span>${h(e.title)}${icon('arrow','sm')}</a>`).join(''):'<p>完成习题自评后，你的记录会出现在这里。</p>'}</div></section></div>`;}

  function roadmapList(s){
    const purpose=current.id==='review'?'review':'learn',list=maps(s.slug,purpose);
    return `<div class="section-head"><h2>${purpose==='learn'?'先建立知识框架':'回顾条件、反例与易混点'}</h2><span class="muted">${list.length} 条${mapLabels[purpose]}</span></div><p class="map-page-intro">${purpose==='learn'?'按概念之间的关系学习一个领域。先速览知识节点，再按需展开陈述和证明。':'沿着专题回顾关键结论，检查适用条件，再做闭卷自测。'}</p><nav class="filters map-purpose-nav" aria-label="选择路线用途">${[['learn','系统学习'],['review','专题复习']].map(([key,label])=>`<a class="filter-chip ${purpose===key?'active':''}" href="${url(s.slug,'roadmaps',key==='review'?'review':'')}" ${purpose===key?'aria-current="page"':''}>${label} <span>${maps(s.slug,key).length}</span></a>`).join('')}<a class="text-link map-practice-link" href="${url(s.slug,'practice')}">去刷题地图 ${icon('arrow','sm')}</a></nav>${list.length?`<div class="roadmap-list">${list.map(e=>roadmapCard(e)).join('')}</div>`:emptyState(purpose==='learn'?'还没有系统学习路线':'还没有专题复习路线','可以先从知识材料中选择一个主题。')}`;
  }
  function practiceList(s){
    const list=maps(s.slug,'practice'),state=filters[`practice-${s.slug}`]??={kind:list.some(e=>!e.study_date)?'topic':'daily',query:'',date:'all'};
    const dates=[...new Set(list.map(e=>e.study_date).filter(Boolean))].sort().reverse();
    return `<div class="section-head"><h2>选一组题，检验这次学到了什么</h2><a class="text-link" href="${url(s.slug,'exercises')}">浏览全部习题 ${icon('arrow','sm')}</a></div><p class="map-page-intro">主题题组用于集中训练，每日题组保留当天的刷题安排。工具卡按需查阅，进度按习题自评计算。</p><div class="filters" role="group" aria-label="筛选刷题地图">${[['topic','主题题组'],['daily','每日题组'],['all','全部题组']].map(([key,label])=>`<button class="filter-chip ${state.kind===key?'active':''}" data-action="practice-kind" data-kind="${key}" aria-pressed="${state.kind===key}">${label} ${list.filter(e=>key==='all'||(key==='daily'?e.study_date:!e.study_date)).length}</button>`).join('')}<label class="inline-search">${icon('search','sm')}<input id="practice-query" type="search" aria-label="搜索刷题地图" placeholder="搜索主题、题号或关键词…" value="${h(state.query)}"></label>${state.kind!=='topic'&&dates.length?`<label class="exercise-date-filter">日期 <select id="practice-date" aria-label="按日期筛选刷题地图"><option value="all">全部日期</option>${dates.map(date=>`<option value="${date}" ${state.date===date?'selected':''}>${date}</option>`).join('')}</select></label>`:''}</div><div id="practice-results"></div>`;
  }
  function updatePracticeResults(){
    const el=document.getElementById('practice-results');if(!el)return;
    const state=filters[`practice-${current.subject}`],words=state.query.trim().toLowerCase().split(/\s+/);
    const list=maps(current.subject,'practice').filter(e=>(state.kind==='all'||(state.kind==='daily'?e.study_date:!e.study_date))&&(state.kind==='topic'||state.date==='all'||e.study_date===state.date)&&words.every(q=>(e.searchText+' '+e.blocks.filter(b=>b.kind==='exercise').map(b=>b.id+' '+entries.get(b.id).title).join(' ').toLowerCase()).includes(q))).sort((a,b)=>(b.study_date??'').localeCompare(a.study_date??'')||(a.order??99)-(b.order??99));
    el.innerHTML=`<p class="result-meta">共 ${list.length} 张刷题地图</p>${list.length?`<div class="practice-map-grid">${list.map(e=>roadmapCard(e,true)).join('')}</div>`:emptyState('没有找到这类题组','试试其他主题、日期，或直接浏览习题库。')}`;
  }
  function render(preserve=false){const y=window.scrollY;const openProofs=preserve?[...document.querySelectorAll('details')].map(d=>d.open):[];current=parseRoute();const s=subjects.get(current.subject);if(!s){app.innerHTML=`<main class="not-found"><h1>还没有这个学科</h1><p>回到数学手记，选择已有学科。</p><a class="btn primary" href="${url(data.subjects[0].slug)}">返回首页</a></main>`;return;}let body='';const e=entries.get(current.id);if(['material','roadmap','exercise','mistake'].includes(current.view)){if(!e||e.subject!==s.slug||e.category!==current.view)body=emptyState('没有找到这个条目','请从当前学科的材料、路线或习题列表重新选择。');else body=({material:materialDetail,roadmap:roadmapDetail,exercise:exerciseDetail,mistake:mistakeDetail})[current.view](e);}else switch(current.view){case'overview':body=overview(s);break;case'materials':body=materialList(s);break;case'roadmaps':body=roadmapList(s);break;case'practice':body=practiceList(s);break;case'exercises':body=exercisesList(s);break;case'mistakes':body=mistakesList(s);break;case'source':body=sourcePage(s);break;case'review':body=reviewPage(s);break;default:body=emptyState('页面不存在','请使用上方导航继续浏览。');}app.innerHTML=shell(s,body);revealActiveTab();document.title=`${e?.subject===s.slug?e.title:s.title} · Folio 数学手记`;updateMaterialResults();updateMistakeResults();updatePracticeResults();if(preserve){document.querySelectorAll('details').forEach((d,i)=>d.open=openProofs[i]??false);window.scrollTo(0,y);}else window.scrollTo(0,0);}
  function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
  function closeModal(){overlays.innerHTML='';document.body.style.overflow='';modalName=null;previousFocus?.focus();}
  function openModal(name,content){previousFocus=document.activeElement;modalName=name;document.body.style.overflow='hidden';overlays.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${name==='search'?'搜索知识':name==='github'?'GitHub 工作流':'学习记录'}">${content}</section></div>`;requestAnimationFrame(()=>overlays.querySelector('input,button,a')?.focus());}
  function openSearch(){openModal('search',`<div class="modal-header">${icon('search')}<input class="modal-search" id="global-query" type="search" placeholder="搜索材料、路线、习题和勘误…" aria-label="搜索知识"><button class="icon-button" data-action="close-modal" aria-label="关闭搜索">${icon('close')}</button></div><div class="modal-scope"><button class="filter-chip active" data-action="search-scope" data-scope="current" aria-pressed="true">当前学科</button><button class="filter-chip" data-action="search-scope" data-scope="all" aria-pressed="false">全部学科</button><span class="spacer"></span><span class="muted" style="font-size:9px">支持中英文与标签</span></div><div class="modal-results" id="global-results"></div><div class="modal-search-footer"><span>在定义之间，寻找联系。</span><span><kbd>Esc</kbd> 关闭</span></div>`);updateSearch();}
  function updateSearch(){const query=(document.getElementById('global-query')?.value??'').trim().toLowerCase();const scope=overlays.querySelector('[data-scope="all"]')?.classList.contains('active');const found=data.entries.filter(e=>(scope||e.subject===current.subject)&&query.split(/\s+/).every(q=>e.searchText.includes(q))).sort((a,b)=>(b.title.toLowerCase().includes(query)?1:0)-(a.title.toLowerCase().includes(query)?1:0)).slice(0,20);const target=document.getElementById('global-results');if(!target)return;target.innerHTML=found.length?found.map(e=>`<a class="search-result" href="${entryUrl(e)}">${badge(e)}<div><strong>${h(e.title)}</strong><p>${h(e.summary)}</p></div><span class="result-context">${h(subjects.get(e.subject).title)}</span></a>`).join(''):emptyState('没有找到相关内容','试试其他名称，或切换到全部学科。');}
  function openGithub(){openModal('github',`<div class="modal-header">${icon('github')}<h2>把数学手记带到 GitHub</h2><button class="icon-button" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body"><p>这个 demo 已按 subject 保存 Markdown 源文件，并附带 GitHub Pages 自动构建工作流。当前尚未连接你的 GitHub 仓库。</p><div class="codebox">subjects/<br>└─ differential-topology/<br>&nbsp;&nbsp; ├─ materials/*.md<br>&nbsp;&nbsp; ├─ roadmaps/*.md<br>&nbsp;&nbsp; └─ exercises/*.md</div><p>在本地修改 Markdown 并推送到你自己的仓库后，工作流会检查内容引用与公式，再构建并发布网页。具体操作写在项目 README 中。</p><p>学习进度保存在浏览器，可单独导出备份；它不会随内容仓库自动同步。</p><div class="row wrap"><button class="btn primary small" data-action="export">${icon('download','sm')}导出学习记录</button><a class="btn secondary small" href="${url(current.subject,'source')}" data-close-link>看看 Markdown 如何变成网页 ${icon('arrow','sm')}</a></div></div>`);}
  function importProgress(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('文件过大');const imported=JSON.parse(await file.text());if(imported.version!==1||!Array.isArray(imported.read)||!imported.exercises||typeof imported.exercises!=='object'||Array.isArray(imported.exercises))throw Error('无效格式');const next={version:1,read:[...new Set(imported.read.filter(id=>entries.get(id)?.category==='material'))],exercises:{},mistakes:{}};for(const [id,value] of Object.entries(imported.exercises)){if(entries.get(id)?.category==='exercise'&&value&&Object.hasOwn(exerciseLabels,value.status)){const maxHints=entries.get(id).blocks.filter(b=>b.kind==='hint').length;next.exercises[id]={status:value.status,hintsUsed:Math.max(0,Math.min(maxHints,Number(value.hintsUsed)||0))};}}for(const [id,value] of Object.entries(imported.mistakes??{})){if(entries.get(id)?.category==='mistake'&&value&&Object.hasOwn(mistakeLabels,value.status)){next.mistakes[id]={status:value.status,note:typeof value.note==='string'?value.note.slice(0,4000):'',...(typeof value.lastReviewedAt==='string'?{lastReviewedAt:value.lastReviewedAt}:{})};}}progress=next;for(const id of Object.keys(exerciseSessions))delete exerciseSessions[id];save();render(true);toast('学习记录已导入');}catch{toast('无法导入，请选择 Folio 导出的有效 JSON 文件');}});input.click();}
  document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;if(notebookAction(target))return;switch(action){case'map-mode':if(entries.get(id)?.category==='roadmap'&&['outline','reading'].includes(target.dataset.mode)){mapModes[id]=target.dataset.mode;render(true);}break;case'practice-kind':filters[`practice-${current.subject}`].kind=target.dataset.kind;filters[`practice-${current.subject}`].date='all';render(true);break;case'menu':document.querySelector('.sidebar')?.classList.add('open');document.querySelector('.sidebar-scrim')?.classList.add('open');break;case'close-menu':document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.sidebar-scrim')?.classList.remove('open');break;case'search':openSearch();break;case'github':openGithub();break;case'close-modal':closeModal();break;case'search-scope':overlays.querySelectorAll('[data-action="search-scope"]').forEach(el=>{const active=el===target;el.classList.toggle('active',active);el.setAttribute('aria-pressed',active);});updateSearch();break;case'filter':filters[current.subject].type=target.dataset.type;document.querySelectorAll('[data-action="filter"]').forEach(el=>{const active=el===target;el.classList.toggle('active',active);el.setAttribute('aria-pressed',active);});updateMaterialResults();break;case'exercise-filter':filters[`ex-${current.subject}`]=target.dataset.type;render(true);break;case'read':if(read(id))progress.read=progress.read.filter(x=>x!==id);else progress.read.push(id);save();render(true);toast(read(id)?'已记录阅读进度':'已取消阅读标记');break;case'source':sourceVisible.has(id)?sourceVisible.delete(id):sourceVisible.add(id);render(true);break;case'hint':{const session=exerciseSessions[id];const max=entries.get(id).blocks.filter(b=>b.kind==='hint').length;session.hints=Math.min(session.hints+1,max);progress.exercises[id]={...progress.exercises[id],status:exerciseState(id)==='new'?'attempted':exerciseState(id),hintsUsed:session.hints};save();render(true);break;}case'solution':exerciseSessions[id].solution=!exerciseSessions[id].solution;if(exerciseState(id)==='new'){progress.exercises[id]={status:'attempted',hintsUsed:exerciseSessions[id].hints};save();}render(true);break;case'assess':progress.exercises[id]={...progress.exercises[id],status:target.dataset.status,hintsUsed:exerciseSessions[id].hints};save();render(true);toast('已保存本次习题自评');break;case'export':download('folio-learning-progress.json',JSON.stringify({...progress,exercises:{...Object.fromEntries(data.entries.filter(e=>e.category==='exercise'&&e.initial_status).map(e=>[e.id,{status:e.initial_status,hintsUsed:0}])),...progress.exercises},exportedAt:new Date().toISOString()},null,2));toast('学习记录已导出');break;case'import':importProgress();break;}});
  document.addEventListener('input',event=>{if(event.target.id==='material-query'){filters[current.subject].query=event.target.value;updateMaterialResults();}if(event.target.id==='global-query')updateSearch();});
  overlays.addEventListener('click',event=>{if(event.target.classList.contains('modal-backdrop'))closeModal();if(event.target.closest('a[href^="#/"]'))closeModal();});
  document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}if(event.key==='Escape'){if(modalName)closeModal();document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.sidebar-scrim')?.classList.remove('open');}if(modalName&&event.key==='Tab'){const focusable=[...overlays.querySelectorAll('a[href],button:not([disabled]),input,select,[tabindex="0"]')].filter(el=>el.offsetParent!==null);if(focusable.length){const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}if(modalName==='search'&&event.key==='Enter'&&event.target.id==='global-query'){const first=overlays.querySelector('.search-result');if(first){location.hash=first.getAttribute('href');closeModal();}}});
  document.addEventListener('input',event=>{if(event.target.id==='practice-query'){filters[`practice-${current.subject}`].query=event.target.value;updatePracticeResults();}if(event.target.id==='mistake-query'){filters[`mistakes-${current.subject}`].query=event.target.value;updateMistakeResults();}});
  document.addEventListener('change',event=>{if(event.target.id==='practice-date'){filters[`practice-${current.subject}`].date=event.target.value;updatePracticeResults();}if(event.target.id==='mistake-status'){filters[`mistakes-${current.subject}`].status=event.target.value;updateMistakeResults();}if(event.target.id==='exercise-date'){filters[`exdate-${current.subject}`]=event.target.value;render(true);}});
  window.addEventListener('hashchange',()=>{if(modalName)closeModal();render();});
  window.addEventListener('storage',event=>{if(event.key===STORAGE){try{const saved=JSON.parse(event.newValue);if(saved?.version===1&&Array.isArray(saved.read)&&saved.exercises){progress=saved;if(!progress.mistakes||typeof progress.mistakes!=='object'||Array.isArray(progress.mistakes))progress.mistakes={};render(true);}}catch{}}});
  render();
})();
